// SPDX-License-Identifier: MIT
pragma solidity >=0.4.22 <0.9.0;

contract Auth {
    uint public userCount = 0;
    uint public employeeCount = 0;
    uint public totalAppointmets = 0;

    mapping(string => user) users;
    mapping(string => employee) employees;
    mapping(address => appointment) appointments;

    struct user {
        string username;
        string password;
        string email;
        string number;
        string userRole;
    }

    struct employee {
        string firstName;
        string lastName;
        string email;
        string number;
        string adr;
        string password;
        string userRole;
    }

    struct appointment {
        address owner;
        string firstName;
        string lastName;
        string email;
        string number;
        string adr;
        string timeSlot;
        string doctor;
    }

    event userCreated(
        string username,
        string email,
        string number,
        string password,
        string userRole
    );

    event employeeCreated(
        string firstName,
        string lastName,
        string email,
        string number,
        string adr,
        string password,
        string userRole
    );

    event appointmentCreated(
        address owner,
        string firstName,
        string lastName,
        string email,
        string number,
        string adr,
        string timeSlot,
        string doctor
    );

    function createUser(
        string memory _username,
        string memory _password,
        string memory _email,
        string memory _number,
        string memory _userRole
    ) public {
        userCount++;
        users[_username] = user(
            _username,
            _password,
            _email,
            _number,
            _userRole
        );
        emit userCreated(_username, _password, _email, _number, _userRole);
    }

    string naam = "Ammar";

    // function getUsername() public view returns (string memory) {
    //     return naam;
    // }

    function getUsername(
        string memory _username
    ) public view returns (string memory) {
        require(
            bytes(users[_username].username).length > 0,
            "User does not exist"
        );
        return users[_username].username;
    }

    function getUserOrEmployeeRole(
        string memory _username
    ) public view returns (string memory) {
        if (
            keccak256(abi.encodePacked(users[_username].userRole)) !=
            keccak256(abi.encodePacked(""))
        ) {
            return users[_username].userRole;
        } else if (
            keccak256(abi.encodePacked(employees[_username].userRole)) !=
            keccak256(abi.encodePacked(""))
        ) {
            return employees[_username].userRole;
        }
        revert("User or employee not found");
    }

    function authenticateLogin(
        string memory _username,
        string memory _password
    ) public view returns (bool) {
        user memory userInstance = users[_username];

        if (bytes(userInstance.username).length == 0) {
            employee memory employeeUser = employees[_username];
            if (bytes(employeeUser.firstName).length == 0) {
                return false;
            } else {
                return
                    keccak256(abi.encodePacked(employeeUser.password)) ==
                    keccak256(abi.encodePacked(_password));
            }
        } else {
            return
                keccak256(abi.encodePacked(userInstance.password)) ==
                keccak256(abi.encodePacked(_password));
        }
    }

    function createEmployee(
        string memory _firstName,
        string memory _lastName,
        string memory _email,
        string memory _number,
        string memory _adr,
        string memory _password,
        string memory _userRole
    ) public {
        employeeCount++;
        employees[_firstName] = employee(
            _firstName,
            _lastName,
            _email,
            _number,
            _adr,
            _password,
            _userRole
        );
        emit employeeCreated(
            _firstName,
            _lastName,
            _email,
            _number,
            _adr,
            _password,
            _userRole
        );
    }

    function bookAppointment(
        string memory _firstName,
        string memory _lastName,
        string memory _email,
        string memory _number,
        string memory _adr,
        string memory _timeSlot,
        string memory _doctor
    ) public {
        totalAppointmets++;
        appointments[msg.sender] = appointment(
            msg.sender,
            _firstName,
            _lastName,
            _email,
            _number,
            _adr,
            _timeSlot,
            _doctor
        );
        emit appointmentCreated(
            msg.sender,
            _firstName,
            _lastName,
            _email,
            _number,
            _adr,
            _timeSlot,
            _doctor
        );
    }

    function getAppointmentCount() public view returns (uint) {
        return totalAppointmets;
    }

    function getAppointment()
        public
        view
        returns (
            string memory,
            string memory,
            string memory,
            string memory,
            string memory,
            string memory,
            string memory
        )
    {
        appointment memory app = appointments[msg.sender];
        return (
            app.firstName,
            app.lastName,
            app.email,
            app.number,
            app.adr,
            app.timeSlot,
            app.doctor
        );
    }
}
